 // RF-002: el IVA va incluido en el precio; se informa, no se suma.
+// RF-004: cada línea puede llevar descuentoPorcentaje (0 a 100), aplicado antes del total y redondeado al centavo.
 export function calcularFactura(items) {
   if (!Array.isArray(items) || items.length === 0) throw new Error("Una factura necesita al menos una línea");
   let totalCentavos = 0;
@@ -15,7 +16,12 @@ export function calcularFactura(items) {
     if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
     if (!Number.isInteger(item.precioUnitarioCentavos) || item.precioUnitarioCentavos < 0)
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
-    totalCentavos += item.cantidad * item.precioUnitarioCentavos;
+    const pct = item.descuentoPorcentaje ?? 0;
+    if (typeof pct !== "number" || !Number.isFinite(pct) || pct < 0 || pct > 100)
+      throw new RangeError("Descuento inválido: debe ser un porcentaje entre 0 y 100");
+    const subtotalCentavos = item.cantidad * item.precioUnitarioCentavos;
+    const descuentoCentavos = Math.round((subtotalCentavos * pct) / 100);
+    totalCentavos += subtotalCentavos - descuentoCentavos;
   }
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
   return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..e3bcea0 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -22,6 +22,23 @@ test("ADR-001: montos en centavos enteros", () => {
   assert.throws(() => calcularFactura([]));
 });

+test("RF-004: descuento por línea (0 a 100), aplicado antes del total y redondeado al centavo", () => {
+  // Ejemplo de docs/specs/facturacion.md: 2 × 10,00 Bs con 10 % → 18,00 Bs
+  const conDescuento = calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000, descuentoPorcentaje: 10 }]);
+  assert.deepEqual(conDescuento, { totalCentavos: 1800, ivaCentavos: 209, netoCentavos: 1591 });
+  // Sin descuento o con 0 % el resultado no cambia
+  assert.equal(calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000 }]).totalCentavos, 2000);
+  assert.equal(calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000, descuentoPorcentaje: 0 }]).totalCentavos, 2000);
+  // Redondeo al centavo: 1 × 0,05 Bs con 33 % → descuento 1,65 centavos → 2 centavos → total 3... se verifica con 1 × 1001 con 50 %
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1001, descuentoPorcentaje: 50 }]).totalCentavos, 501);
+  // 100 % deja la línea en cero
+  assert.equal(calcularFactura([{ cantidad: 3, precioUnitarioCentavos: 500, descuentoPorcentaje: 100 }]).totalCentavos, 0);
+  // Fuera de 0–100 se rechaza
+  assert.throws(() => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje: -1 }]), RangeError);
+  assert.throws(() => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje: 101 }]), RangeError);
+  assert.throws(() => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje: "10" }]), RangeError);
+});
